package com.hbm.client.silex;
import com.hbm.machine.silex.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
@WailaPlugin public final class SilexJadePlugin implements IWailaPlugin {
 @Override public void register(IWailaCommonRegistration event){event.registerBlockDataProvider(Provider.INSTANCE,SilexBlockEntity.class);event.registerBlockDataProvider(Provider.INSTANCE,SilexPort.class);}@Override public void registerClient(IWailaClientRegistration event){event.registerBlockComponent(Provider.INSTANCE,SilexBlock.class);}
 private enum Provider implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return SilexContent.id("silex_state");}@Override public void appendServerData(CompoundTag tag,BlockAccessor accessor){var tile=accessor.getBlockEntity();if(tile instanceof SilexPort port)tile=port.core();if(tile instanceof SilexBlockEntity machine){tag.putString("hbm:silex_wave",machine.mode.name());if(!machine.current.isEmpty())tag.put("hbm:silex_current",machine.current.save(accessor.getLevel().registryAccess()));}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor accessor,IPluginConfig config){var tag=accessor.getServerData();if(tag.contains("hbm:silex_current")){var stack=ItemStack.parseOptional(accessor.getLevel().registryAccess(),tag.getCompound("hbm:silex_current"));if(!stack.isEmpty())tooltip.add(stack.getHoverName());}if(tag.contains("hbm:silex_wave")){var wave=LaserWavelength.valueOf(tag.getString("hbm:silex_wave"));if(wave!=LaserWavelength.NULL)tooltip.add(Component.translatable(wave.nameKey).withStyle(wave.textColor));}}}
}
